INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('jawa', 'Jawa', 'https://images.unsplash.com/photo-1588668214407-6ea9a6d8c272?auto=format&fit=crop&w=1200&q=80', 'Pusat peradaban megah, candi bersejarah, dan kriya bernilai tinggi.', 'Pulau Jawa adalah jantung peradaban Nusantara dengan warisan kerajaan Mataram, Majapahit, dan Pajajaran. Dikenal di seluruh dunia atas mahakarya Candi Borobudur, kemegahan Prambanan, serta kehalusan filosofi Batik dan alunan Gamelan.', 'Selamat datang di Pulau Jawa. Pusat peradaban candi bersejarah, filosofi seni batik yang mendalam, dan tradisi keraton yang abadi.', '{\"wilayah\":\"128.297 km²\",\"budaya\":\"150+ Kesenian Adat\",\"ikon\":\"Candi Borobudur\"}', '[\"Batik Tulis & Cap\",\"Candi Borobudur & Prambanan\",\"Angklung Sunda\",\"Ukiran Kayu Jepara\",\"Wayang Kulit\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('sumatra', 'Sumatra', 'https://images.unsplash.com/photo-1596402184320-417e7178b2cd?auto=format&fit=crop&w=1200&q=80', 'Tanah rempah, arsitektur gonjong nan megah, dan kekayaan alam memukau.', 'Sumatra membentang dari ujung barat dengan keanekaragaman etnis Minang, Batak, Melayu, dan Aceh. Memiliki arsitektur ikonik Rumah Gadang bersudut tanduk kerbau, kuliner legendaris Rendang, serta kemegahan Danau Toba.', 'Menjelajahi Pulau Sumatra. Tanah Minangkabau dengan Rumah Gadang nan megah, Danau Toba yang mempesona, dan kuliner rendang yang mendunia.', '{\"wilayah\":\"473.481 km²\",\"budaya\":\"200+ Tradisi Suku\",\"ikon\":\"Rumah Gadang\"}', '[\"Rumah Gadang Minangkabau\",\"Rendang Daging\",\"Gondang Batak\",\"Tari Piring\",\"Danau Toba\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('bali', 'Bali', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80', 'Harmoni sakral antara seni, spiritualitas, dan keindahan alam dewata.', 'Pulau Dewata terkenal dengan falsafah Tri Hita Karana yang menyelaraskan manusia, alam, dan Sang Pencipta. Menampilkan tarian sakral Kecak di tebing laut, ornamen ukir pura yang magis, dan keramahan masyarakatnya.', 'Pulau Bali. Keindahan seni dan ritual yang menyatu dalam detak kehidupan sehari-hari, dari Tari Kecak hingga harmoni Pura dewata.', '{\"wilayah\":\"5.780 km²\",\"budaya\":\"80+ Upacara Adat\",\"ikon\":\"Tari Kecak Uluwatu\"}', '[\"Tari Kecak & Barong\",\"Sate Lilit Ikan\",\"Gamelan Gong Kebyar\",\"Upacara Ngaben\",\"Pura Besakih\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('kalimantan', 'Kalimantan', 'https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=1200&q=80', 'Paru-paru dunia dengan kearifan suku Dayak dan rumah panggung legendaris.', 'Kalimantan menyimpan rimba tropis purba dan peradaban sungai yang kaya. Suku Dayak mewariskan Rumah Betang tempat ratusan keluarga hidup rukun, alunan merdu alat musik Sampe, dan tarian sakral Hudoq.', 'Pulau Kalimantan. Hutan khatulistiwa yang asri dengan kearifan Rumah Betang suku Dayak dan petikan dawai Sampe yang menenangkan jiwa.', '{\"wilayah\":\"743.330 km²\",\"budaya\":\"400+ Sub-suku Dayak\",\"ikon\":\"Rumah Betang Dayak\"}', '[\"Rumah Betang Panjang\",\"Tari Topeng Hudoq\",\"Alat Musik Sampe\",\"Ukiran Perisai Dayak\",\"Susur Sungai Kapuas\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('sulawesi', 'Sulawesi', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80', 'Ketangguhan pelaut Bugis-Makassar dan kemegahan ritus adat Toraja.', 'Sulawesi memiliki garis pantai eksotis dengan tradisi kapal Pinisi yang menjelajahi samudra dunia. Di dataran tingginya, masyarakat Toraja menjaga arsitektur Tongkonan dan upacara penghormatan leluhur Rambu Solo.', 'Pulau Sulawesi. Negeri pelaut tangguh perahu Pinisi dan kekaguman arsitektur adat Tongkonan Toraja yang sarat makna.', '{\"wilayah\":\"174.600 km²\",\"budaya\":\"120+ Warisan Maritim & Ritus\",\"ikon\":\"Tongkonan Toraja\"}', '[\"Rumah Tongkonan Toraja\",\"Kapal Pinisi Bugis\",\"Coto Makassar\",\"Tari Pa\'gellu\",\"Taman Laut Bunaken\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('nusa-tenggara', 'Nusa Tenggara', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80', 'Surga savana eksotis, tenun ikat bernilai tinggi, dan habitat naga Komodo.', 'Gugusan pulau Nusa Tenggara Barat dan Timur menyuguhkan lanskap savana dramatis, tenun ikat dengan pewarna alami bernilai seni tinggi, alat musik Sasando dari daun lontar, serta satwa purba Komodo.', 'Nusa Tenggara. Gugusan pulau savana eksotis dengan mahakarya Tenun Ikat, lantunan merdu Sasando, dan keajaiban Pulau Komodo.', '{\"wilayah\":\"68.870 km²\",\"budaya\":\"90+ Corak Tenun Ikat\",\"ikon\":\"Tenun Sumba & Komodo\"}', '[\"Tenun Ikat Tradisional\",\"Alat Musik Sasando\",\"Taman Nasional Komodo\",\"Desa Adat Wae Rebo\",\"Kuda Pasola\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('maluku', 'Maluku', 'https://images.unsplash.com/photo-1559827291-72ebf3d20d4c?auto=format&fit=crop&w=1200&q=80', 'Kepulauan rempah legendaris yang mengubah jalur perdagangan samudra.', 'Maluku tersohor sejak abad pertengahan sebagai pusat cengkih dan pala dunia. Dikaruniai pesona laut biru kristal, tarian perang heroik Cakalele, dan tradisi persaudaraan Pela Gandong.', 'Kepulauan Maluku. Jalur rempah pala dan cengkih yang pernah mengguncang dunia, diiringi semangat juang Tari Cakalele.', '{\"wilayah\":\"78.896 km²\",\"budaya\":\"60+ Tarian & Musik Bahari\",\"ikon\":\"Jalur Rempah Pala\"}', '[\"Kuliner Papeda Kuah Kuning\",\"Tari Perang Cakalele\",\"Alat Musik Tifa\",\"Benteng Bersejarah Banda\",\"Pela Gandong\"]');
INSERT INTO `islands` (`slug`, `name`, `image`, `tagline`, `description`, `narration`, `stats`, `highlights`) VALUES ('papua', 'Papua', 'https://images.unsplash.com/photo-1597655601841-214a4cfe8b2c?auto=format&fit=crop&w=1200&q=80', 'Bentang alam megah surga timur, tas noken dunia, dan ukiran Asmat.', 'Tanah Papua adalah mahkota timur Indonesia dengan kekayaan laut terkaya di planet bumi di Raja Ampat, tas rajut serat kulit kayu Noken yang diakui UNESCO, serta seni pahat patung suku Asmat yang dihormati museum dunia.', 'Tanah Papua. Surga bawah laut terindah Raja Ampat, keunikan tas Noken warisan dunia UNESCO, dan ketelitian ukiran suku Asmat.', '{\"wilayah\":\"421.981 km²\",\"budaya\":\"250+ Bahasa & Suku\",\"ikon\":\"Raja Ampat & Noken\"}', '[\"Kepulauan Karst Raja Ampat\",\"Tas Noken Kulit Kayu\",\"Ukiran Kayu Asmat\",\"Tifa Papua\",\"Lembah Baliem\"]');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('rendang', 'Rendang', 'Makanan', 'sumatra', 'Sumatra Barat', 'Mahakarya kuliner Minangkabau: daging dimasak perlahan dengan santan dan rempah melimpah hingga meresap sempurna dan berwarna gelap karamel.', 'Rendang bukan sekadar masakan, tetapi cerminan kesabaran dan kebersamaan orang Minang. Proses memasaknya bisa memakan waktu berjam-jam hingga bumbu mengering dan awet disimpan lama.', 'https://ichef.bbci.co.uk/ace/ws/640/cpsprodpb/17A7A/production/_102609869_rendanggettysatu.jpg.webp', '[{\"src\":\"https:\\/\\/www.dailymeatrecipe.com\\/wp-content\\/uploads\\/2025\\/07\\/Beef-Rendang-Recipe.webp\",\"caption\":\"Penyajian Rendang Daging Sapi dengan bumbu pekat berminyak alami\"},{\"src\":\"https:\\/\\/image.idntimes.com\\/post\\/20250122\\/1542px-memasak-rendang-59f506aa441e3192bb4237a4e87b2a36-7875d0d5fe6d24dc396302de528f1f39.jpg?tr=w-1200\",\"caption\":\"Proses memasak rendang dengan api kuali yang besar dan tradisional\"},{\"src\":\"https:\\/\\/www.jamrocksportsbarandgrill.com\\/wp-content\\/uploads\\/2026\\/02\\/Proses-Pembuatan-Rendang-Tradisional-yang-Kaya-Rempah-788x520.jpg\",\"caption\":\"Rempah-rempah asli Nusantara: serai, lengkuas, jahe, dan cabai merah keriting\"}]', '[\"Rendang pernah dinobatkan CNN sebagai salah satu makanan terlezat di dunia.\",\"Empat bahan utamanya sering dimaknai sebagai simbol unsur masyarakat Minang yang bermusyawarah: daging, kelapa, cabai, dan bumbu.\"]', 'Unsplash / Kuliner Minang');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sate-padang', 'Sate Padang', 'Makanan', 'sumatra', 'Padang, Sumatra Barat', 'Sate daging sapi dengan kuah kental kuning kecokelatan beraroma rempah, disajikan bersama ketupat dan taburan bawang goreng.', 'Sate Padang punya beberapa gaya, seperti Padang Panjang, Pariaman, dan Padang Kota, yang dibedakan oleh warna dan kepedasan kuahnya. Daging direbus bersama rempah sebelum dibakar sebentar di atas bara.', 'https://sumbarzone.com/wp-content/uploads/2024/06/sate-padang-2.jpeg', '[{\"src\":\"https:\\/\\/static.vecteezy.com\\/system\\/resources\\/thumbnails\\/015\\/957\\/916\\/small_2x\\/sate-padang-or-satay-padang-is-spicy-beef-satay-from-padang-west-sumatra-served-with-spicy-curry-sauce-and-rice-cake-lontong-on-banana-leaf-isolated-on-white-background-photo.jpg\",\"caption\":\"Sate Padang dengan kuah kental beraroma rempah dan taburan bawang goreng yang di sajikan di atas daun pisang\"},{\"src\":\"https:\\/\\/kediripedia.com\\/wp-content\\/uploads\\/2020\\/01\\/sate-padang-1024x683.jpg\",\"caption\":\"Proses pembakaran tusukan daging di atas arang batok kelapa\"},{\"src\":\"https:\\/\\/static.vecteezy.com\\/system\\/resources\\/thumbnails\\/015\\/957\\/916\\/small_2x\\/sate-padang-or-satay-padang-is-spicy-beef-satay-from-padang-west-sumatra-served-with-spicy-curry-sauce-and-rice-cake-lontong-on-banana-leaf-isolated-on-white-background-photo.jpg\",\"caption\":\"Penyajian dengan ketupat potong dalam pincuk daun pisang\"}]', '[\"Kuahnya dikentalkan dengan tepung beras dan dibumbui puluhan jenis rempah.\",\"Selain daging, isian sate yang lazim adalah lidah dan jeroan sapi.\"]', 'Unsplash / Musik Tradisional Batak');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('pempek', 'Pempek Palembang', 'Makanan', 'sumatra', 'Palembang, Sumatra Selatan', 'Olahan ikan dan sagu yang kenyal gurih, disajikan dengan kuah cuko asam manis pedas.', 'Pempek hadir dalam banyak bentuk: kapal selam berisi telur, lenjer, adaan, hingga kulit. Kuah cuko dibuat dari gula, cuka, bawang putih, dan cabai yang menyeimbangkan rasa gurih ikannya.', 'https://radarmukomuko.disway.id/upload/cc047869d0bff7ad27a0956ced9d1d63.jpg', '[{\"src\":\"https:\\/\\/www.pinterpolitik.com\\/wp-content\\/uploads\\/2023\\/09\\/foto-radarmukomuko-dot-disway-dot-id.webp\",\"caption\":\"Pempek Kapal Selam digoreng garing dengan kuah cuko hitam kental\"},{\"src\":\"https:\\/\\/www.dandapala.com\\/assets\\/back\\/article\\/img\\/compress\\/menilik-kreativitas-wong-kito-galo-dalam-ragam-jenis-pempek-thumbnail.jpg\",\"caption\":\"Aneka ragam pempek\"},{\"src\":\"https:\\/\\/awsimages.detik.net.id\\/community\\/media\\/visual\\/2024\\/10\\/01\\/cuko-pempek-palembang_43.jpeg?w=700&q=90\",\"caption\":\"Cuko pempek asli dari gula aren dan cabai rawit\"}]', '[\"Menurut cerita populer, nama pempek berasal dari sebutan \\\"apek\\\" bagi penjual keturunan Tionghoa yang dahulu menjajakannya.\",\"Pempek kapal selam adalah varian paling dikenal karena isian telur ayam utuhnya.\"]', 'Unsplash / Tari Tradisional Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('songket-palembang', 'Songket Palembang', 'Pakaian', 'sumatra', 'Palembang, Sumatra Selatan', 'Kain tenun mewah bersulam benang emas yang dijuluki \"ratu segala kain\", lambang kemegahan budaya Melayu Palembang.', 'Songket ditenun tangan dengan menyisipkan benang emas atau perak ke dalam kain dasar sehingga membentuk motif timbul. Dahulu kain ini identik dengan busana bangsawan dan perhelatan adat besar.', 'https://indonesiaexpat.id/wp-content/uploads/2023/11/Main-Image-Songket-Palembang-by-Digstraksi.jpg', '[{\"src\":\"https:\\/\\/enimekspres.disway.id\\/upload\\/1cc69ea7a4a1a549b6540051b43d1d75.jpg\",\"caption\":\"Kilau benang emas motif songket Lepus Palembang\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=1200&auto=format&fit=crop\",\"caption\":\"Pengrajin perempuan menenun helai demi helai di alat tenun gedogan\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1544816155-12df9643f363?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Busana adat kebesaran pengantin Palembang Aesan Gede berbahan songket\"}]', '[\"Motif seperti lepus dan bunga tanjung menjadi ciri khas songket Palembang.\",\"Selembar songket halus bisa memakan waktu berminggu-minggu hingga berbulan-bulan untuk ditenun.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('ulos-batak', 'Ulos Batak', 'Pakaian', 'sumatra', 'Sumatra Utara', 'Kain tenun sakral suku Batak yang melambangkan kehangatan, restu, dan kasih sayang, dipakai dalam hampir semua upacara adat.', 'Ulos tidak hanya dikenakan, tetapi juga diberikan sebagai bentuk doa dan penghormatan. Setiap jenis ulos memiliki warna, motif, dan peruntukan sendiri sesuai acara dan penerimanya.', 'https://floodlove.net/wp-content/uploads/2022/12/Jenis-jenis-Ulos-Batak.webp', '[{\"src\":\"https:\\/\\/floodlove.net\\/wp-content\\/uploads\\/2022\\/12\\/Jenis-jenis-Ulos-Batak.webp\",\"caption\":\"Ulos Batak - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ulos Batak - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ulos Batak - Warisan budaya luhur\"}]', '[\"Tradisi mangulosi adalah prosesi menyelimutkan ulos kepada seseorang sebagai tanda restu.\",\"Ulos kerap diberikan oleh pihak orang tua atau yang dituakan kepada anak, menantu, atau cucu dalam upacara adat.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('pakaian-adat-minang', 'Busana Adat Minangkabau', 'Pakaian', 'sumatra', 'Sumatra Barat', 'Busana pengantin dan kebesaran Minang dengan baju kurung beludru, kain songket, dan suntiang, mahkota logam bertingkat di kepala perempuan.', 'Busana ini mencerminkan kedudukan perempuan Minang dalam sistem matrilineal. Suntiang yang berkilau dan bergoyang menjadi pusat perhatian sekaligus simbol kehormatan.', 'https://i.pinimg.com/originals/9e/c5/66/9ec566302570efc8d57e8e4b6adf9987.jpg?nii=t', '[{\"src\":\"https:\\/\\/i.pinimg.com\\/originals\\/9e\\/c5\\/66\\/9ec566302570efc8d57e8e4b6adf9987.jpg?nii=t\",\"caption\":\"Busana Adat Minangkabau - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Busana Adat Minangkabau - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Busana Adat Minangkabau - Warisan budaya luhur\"}]', '[\"Suntiang dapat berbobot beberapa kilogram sehingga pemakainya harus berlatih menahan beban di kepala.\",\"Bentuk dan jumlah hiasan suntiang berbeda antar daerah (nagari) di Sumatra Barat.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tari-saman', 'Tari Saman', 'Tradisi', 'sumatra', 'Gayo Lues, Aceh', 'Tarian dari dataran tinggi Gayo yang menampilkan puluhan penari bersila dengan tepukan tangan dan dada yang serempak dan cepat.', 'Saman biasa dibawakan dalam acara adat dan perayaan penting masyarakat Gayo. Keseragaman gerak dan syair yang dilantunkan bersama menjadi inti pertunjukannya.', 'https://static.cdntap.com/tap-assets-prod/wp-content/uploads/sites/24/2021/07/tari-4-1.jpg?width=700&quality=80', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Deretan penari Saman bergerak dalam sinkronisasi sempurna dan cepat\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pola gerak serong dan lentikan tubuh suku Gayo nan energik\"},{\"src\":\"https:\\/\\/blogger.googleusercontent.com\\/img\\/b\\/R29vZ2xl\\/AVvXsEh-SVgko2JTImRwC-3dGIE_3V2WjQDWi7UenMIhf0SnGo1CmJttJpxxnV_hwox08fANXpSsoel0tv8TE_aAoA78rFTVnMoAuE81Fy1IbGc-1gnbvt3CXADlaPPYzqjppkYJ0hauREqYDMQ\\/s1600\\/Industri-Batik-Hadapi-MEA-271015-Prad-1.jpg\",\"caption\":\"Detail motif tenun kerawang Gayo pada busana penari Saman\"}]', '[\"UNESCO mengakui Tari Saman sebagai Warisan Budaya Takbenda pada 2011.\",\"Tari ini tidak memakai alat musik; ritmenya lahir dari tepukan dan suara penari sendiri.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('lompat-batu-nias', 'Lompat Batu Nias (Fahombo)', 'Tradisi', 'sumatra', 'Pulau Nias, Sumatra Utara', 'Tradisi pemuda Nias melompati susunan batu setinggi sekitar dua meter sebagai bukti ketangkasan dan kedewasaan.', 'Fahombo dahulu menjadi latihan ketangkasan prajurit untuk melompati benteng desa musuh. Kini tradisi ini dipertunjukkan di desa adat seperti Bawomataluo dan menjadi kebanggaan masyarakat Nias.', 'https://2.bp.blogspot.com/-TEqWsjKt3cY/UJ0N8NwVWBI/AAAAAAAAAJg/P-X1V-9D1Cg/s1600/Lompat+Batu+Nias.JPG', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pemuda Nias melayang di udara melompati monolit batu Hombo\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Desa adat Bawomataluo dengan deretan rumah panggung Omo Sebua\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1544816155-12df9643f363?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Baju adat perang Nias warna kuning dan merah mencolok\"}]', '[\"Tumpukan batu yang dilompati tingginya sekitar dua meter.\",\"Pemuda yang berhasil melompat dianggap telah dewasa dan dihormati di desanya.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('pacu-jalur', 'Pacu Jalur', 'Tradisi', 'sumatra', 'Kuantan Singingi, Riau', 'Lomba dayung perahu kayu panjang yang diawaki puluhan pendayung di Sungai Batang Kuantan.', 'Jalur dibuat dari satu batang pohon besar yang dilubangi, dan pengerjaannya melibatkan ritual serta gotong royong warga. Di haluan jalur berdiri anak coki yang menari memberi semangat pendayung.', 'https://api.kemenpar.go.id/storage/app/uploads/public/688/c94/6b4/thumb_14595_1200_630_0_0_crop.jpg', '[{\"src\":\"https:\\/\\/api.kemenpar.go.id\\/storage\\/app\\/uploads\\/public\\/688\\/c94\\/6b4\\/thumb_14595_1200_630_0_0_crop.jpg\",\"caption\":\" Perahu viral jalur beradu cepat di Sungai Batang Kuantan\"},{\"src\":\"https:\\/\\/images.bisnis.com\\/posts\\/2025\\/07\\/02\\/1889814\\/pacu_jalur_1751443671.jpg\",\"caption\":\"Puluhan pendayung mendayung serempak dengan energi maksimal\"},{\"src\":\"https:\\/\\/asset.mediaindonesia.com\\/news\\/2025\\/08\\/19\\/1755558617_1a0cbac0abf7ddec3aa1.jpg\",\"caption\":\"Suasana riuh ribuan penonton memadati tepian sungai festival\"}]', '[\"Tradisi ini diperkirakan telah berlangsung sejak berabad-abad lalu di tepian Sungai Kuantan.\",\"Satu jalur dapat diawaki puluhan pendayung yang harus kompak mendayung serempak.\"]', 'Unsplash / Tradisi Perahu Riau');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('gudeg', 'Gudeg Yogyakarta', 'Makanan', 'jawa', 'Yogyakarta', 'Nangka muda yang dimasak lama bersama gula aren, santan, dan daun jati hingga berwarna cokelat dan berasa manis legit.', 'Gudeg biasa disajikan dengan nasi, ayam, telur pindang, tahu-tempe, dan sambal krecek yang pedas. Perpaduan manis dan pedasnya menjadi identitas kuliner Yogyakarta.', 'https://img.freepik.com/premium-photo/close-up-gudeg-komplit-signature-legendary-dish-from-yogyakarta-indonesia-jack-fruit-stew-accompanied-with-spicy-stew-cattle-skin-crackers-brown-eggs-tofu-tempeh-sambal_511235-5876.jpg?w=2000', '[{\"src\":\"https:\\/\\/kediripedia.com\\/wp-content\\/uploads\\/2020\\/01\\/sate-padang-1024x683.jpg\",\"caption\":\"Satu porsi komplit Gudeg dengan sambal krecek, ayam kampung, dan telur pindang\"},{\"src\":\"https:\\/\\/www.jamrocksportsbarandgrill.com\\/wp-content\\/uploads\\/2026\\/02\\/Proses-Pembuatan-Rendang-Tradisional-yang-Kaya-Rempah-788x520.jpg\",\"caption\":\"Proses memasak gudeg di dalam kuali tanah liat besar berjam-jam\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Gudeg basah disiram areh santan kental yang gurih di warung lesehan\"}]', '[\"Daun jati yang ikut dimasak memberi warna cokelat kemerahan alami.\",\"Gudeg kering tahan lebih lama sehingga populer sebagai oleh-oleh.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('rawon', 'Rawon', 'Makanan', 'jawa', 'Jawa Timur', 'Sup daging sapi berkuah hitam pekat dari kluwek, disajikan dengan tauge pendek, telur asin, dan sambal.', 'Kluwek memberi rawon warna gelap dan rasa gurih khas yang sulit ditiru. Hidangan ini lazim ditemui di Surabaya dan sekitarnya, biasanya dimakan dengan kerupuk dan sambal terasi.', ' https://kabarbaru.co/wp-content/uploads/2022/02/Rawon-800x533.jpg', '[{\"src\":\" https:\\/\\/kabarbaru.co\\/wp-content\\/uploads\\/2022\\/02\\/Rawon-800x533.jpg\",\"caption\":\"Rawon - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Rawon - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Rawon - Warisan budaya luhur\"}]', '[\"Kluwek berasal dari biji pohon pangi (Pangium edule) yang harus diolah dahulu agar aman dimakan.\",\"Tauge pendek dan telur asin adalah pelengkap khas rawon Jawa Timur.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('lumpia-semarang', 'Lumpia Semarang', 'Makanan', 'jawa', 'Semarang, Jawa Tengah', 'Gulungan kulit tipis berisi rebung, telur, dan udang atau ayam, hasil perpaduan kuliner Tionghoa dan Jawa.', 'Lumpia Semarang dapat dinikmati goreng maupun basah, disantap dengan saus kental manis gurih dan acar. Isian rebungnya memberi aroma dan tekstur khas.', 'https://img-global.cpcdn.com/recipes/b052fb8eea6aab1f/680x482cq70/lumpia-semarang-foto-resep-utama.jpg', '[{\"src\":\"https:\\/\\/img-global.cpcdn.com\\/recipes\\/b052fb8eea6aab1f\\/680x482cq70\\/lumpia-semarang-foto-resep-utama.jpg\",\"caption\":\"Lumpia Semarang - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Lumpia Semarang - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Lumpia Semarang - Warisan budaya luhur\"}]', '[\"Lumpia Semarang dikenal sebagai hasil akulturasi budaya Tionghoa dan Jawa.\",\"Rebung (bambu muda) menjadi bahan isian yang menjadi ciri khasnya.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('batik', 'Batik Tulis', 'Pakaian', 'jawa', 'Yogyakarta & Solo, Jawa Tengah', 'Kain bermotif filosofis yang digambar dengan canting dan malam panas, diakui UNESCO sebagai warisan budaya dunia.', 'Setiap motif batik membawa makna dan doa, misalnya Parang yang melambangkan keteguhan atau Truntum yang berarti cinta yang tumbuh kembali. Proses canting menuntut ketelatenan tinggi.', 'https://images.unsplash.com/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=1200&auto=format&fit=crop\",\"caption\":\"Proses menorehkan canting lilin malam panas di atas lembaran kain\"},{\"src\":\"https:\\/\\/www.yupiland.com\\/assets\\/images\\/blog%202023\\/Contoh%20Batik\\/Batik%20Sogan.webp\",\"caption\":\"Motif klasik batik sogan dengan warna cokelat dan nila alami\"},{\"src\":\"https:\\/\\/blogger.googleusercontent.com\\/img\\/b\\/R29vZ2xl\\/AVvXsEh-SVgko2JTImRwC-3dGIE_3V2WjQDWi7UenMIhf0SnGo1CmJttJpxxnV_hwox08fANXpSsoel0tv8TE_aAoA78rFTVnMoAuE81Fy1IbGc-1gnbvt3CXADlaPPYzqjppkYJ0hauREqYDMQ\\/s1600\\/Industri-Batik-Hadapi-MEA-271015-Prad-1.jpg\",\"caption\":\"Proses penjemuran kain batik setelah pewarnaan alami di pekarangan\"}]', '[\"UNESCO menetapkan Batik Indonesia sebagai Warisan Budaya Takbenda pada 2 Oktober 2009, yang kini diperingati sebagai Hari Batik Nasional.\",\"Di keraton tertentu ada motif larangan yang hanya boleh dikenakan keluarga raja.\"]', 'Unsplash / Seni Batik Jawa');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('kebaya', 'Kebaya Jawa', 'Pakaian', 'jawa', 'Jawa Tengah & Yogyakarta', 'Atasan perempuan berpotongan anggun yang dipadukan dengan jarik batik dan sanggul, busana khas perempuan Jawa.', 'Kebaya Jawa biasanya dikenakan bersama kain jarik dan stagen sehingga membentuk siluet yang rapi dan berwibawa. Busana ini dipakai pada upacara adat, pernikahan, dan acara resmi.', 'https://weddingmarket.com/storage/images/artikelideacontent/new/7890342456acc9aed3d41a373928230402a428ed.webp', '[{\"src\":\"https:\\/\\/weddingmarket.com\\/storage\\/images\\/artikelideacontent\\/new\\/7890342456acc9aed3d41a373928230402a428ed.webp\",\"caption\":\"Kebaya Jawa - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kebaya Jawa - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kebaya Jawa - Warisan budaya luhur\"}]', '[\"Kebaya menjadi bagian nominasi bersama beberapa negara untuk pengakuan UNESCO.\",\"Cara memakai jarik dan lipatan wiru punya aturan tersendiri dalam tata busana Jawa.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('beskap-blangkon', 'Beskap & Blangkon', 'Pakaian', 'jawa', 'Yogyakarta & Surakarta', 'Busana adat pria Jawa berupa beskap, kain batik, keris, dan penutup kepala blangkon.', 'Beskap adalah jas tertutup yang dipadukan dengan jarik dan blangkon dalam upacara adat serta pertunjukan seni. Kelengkapan busana ini mencerminkan sikap tertib dan sopan.', 'https://down-id.img.susercontent.com/file/84d92bf8d48270ad15be674976fde826', '[{\"src\":\"https:\\/\\/down-id.img.susercontent.com\\/file\\/84d92bf8d48270ad15be674976fde826\",\"caption\":\"Beskap & Blangkon - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Beskap & Blangkon - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Beskap & Blangkon - Warisan budaya luhur\"}]', '[\"Blangkon gaya Yogyakarta memiliki tonjolan di belakang (mondholan), sedangkan gaya Solo cenderung datar.\",\"Keris yang diselipkan di punggung melengkapi busana adat pria Jawa dalam upacara tertentu.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('wayang-kulit', 'Wayang Kulit', 'Tradisi', 'jawa', 'Jawa Tengah & Jawa Timur', 'Pertunjukan bayangan boneka kulit yang digerakkan dalang dengan iringan gamelan, membawakan kisah Mahabharata dan Ramayana.', 'Dalang memainkan semua tokoh, mengubah suara, dan menyampaikan petuah lewat cerita. Pertunjukan semalam suntuk adalah bagian dari tradisi dalam hajatan dan upacara besar.', 'https://www.indonesia.travel/contentassets/1ee02702541042c38e6841435fb28318/wayang_banner.jpg', '[{\"src\":\"https:\\/\\/www.indonesia.travel\\/contentassets\\/1ee02702541042c38e6841435fb28318\\/wayang_banner.jpg\",\"caption\":\"Wayang Kulit - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Wayang Kulit - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Wayang Kulit - Warisan budaya luhur\"}]', '[\"UNESCO menetapkan wayang sebagai karya agung warisan budaya lisan dan takbenda pada 2003.\",\"Dalang dalam satu pertunjukan memerankan seluruh tokoh sekaligus mengendalikan iringan musik.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sekaten', 'Sekaten', 'Tradisi', 'jawa', 'Yogyakarta & Surakarta', 'Perayaan Maulid Nabi di lingkungan keraton, ditandai gamelan pusaka dan kirab gunungan hasil bumi.', 'Sekaten diselenggarakan dengan memainkan gamelan pusaka di halaman masjid agung dan diakhiri Grebeg Maulud, ketika gunungan diarak lalu diperebutkan warga. Perayaan ini memadukan nilai keagamaan dan tradisi keraton.', 'https://s1.dmcdn.net/v/X0dwS1d0-DhYmA6PE/x720', '[{\"src\":\"https:\\/\\/s1.dmcdn.net\\/v\\/X0dwS1d0-DhYmA6PE\\/x720\",\"caption\":\"Sekaten - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Sekaten - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Sekaten - Warisan budaya luhur\"}]', '[\"Gamelan Sekaten hanya dimainkan pada perayaan ini dan dianggap pusaka keraton.\",\"Gunungan berisi hasil bumi dan diyakini membawa berkah bagi yang mendapatkannya.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('reog-ponorogo', 'Reog Ponorogo', 'Tradisi', 'jawa', 'Ponorogo, Jawa Timur', 'Seni pertunjukan dengan topeng singa raksasa berhias bulu merak yang ditopang penari dengan kekuatan gigi dan leher.', 'Reog menampilkan Singa Barong, warok, dan penari jathil dalam pertunjukan yang gagah dan dramatis. Kisahnya berakar dari legenda dan sindiran terhadap penguasa pada masa lalu.', 'https://cdngnfi2.sgp1.digitaloceanspaces.com/gnfi/uploads/images/2024/10/1024px-tarian-reog-ponorogojpg', '[{\"src\":\"https:\\/\\/cdngnfi2.sgp1.digitaloceanspaces.com\\/gnfi\\/uploads\\/images\\/2024\\/10\\/1024px-tarian-reog-ponorogojpg\",\"caption\":\"Reog Ponorogo - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Reog Ponorogo - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Reog Ponorogo - Warisan budaya luhur\"}]', '[\"Topeng dadak merak berbobot puluhan kilogram sehingga penarinya membutuhkan kekuatan khusus.\",\"Warok adalah tokoh yang dihormati karena kewibawaan dan ilmu kanuragannya.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sate-lilit', 'Sate Lilit', 'Makanan', 'bali', 'Bali', 'Daging atau ikan cincang berbumbu basa genep yang dililitkan pada batang serai atau bambu lalu dibakar.', 'Adonan sate lilit dicampur kelapa parut dan rempah khas Bali sehingga gurih dan harum. Penyajiannya sering ditemani sambal matah dan nasi.', 'https://bisnisusahaonline.com/wp-content/uploads/2021/10/1610275052814-sate-lilit.jpg', '[{\"src\":\"https:\\/\\/www.jamrocksportsbarandgrill.com\\/wp-content\\/uploads\\/2026\\/02\\/Proses-Pembuatan-Rendang-Tradisional-yang-Kaya-Rempah-788x520.jpg\",\"caption\":\"Sate lilit batang serai yang dipanggang harum di atas bara arang\"},{\"src\":\"https:\\/\\/kediripedia.com\\/wp-content\\/uploads\\/2020\\/01\\/sate-padang-1024x683.jpg\",\"caption\":\"Penyajian sate lilit dengan sambal matah segar dan nasi campur Bali\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bumbu rempah basa genep khas pulau Dewata yang kaya kunyit dan terasi\"}]', '[\"Berbeda dari sate biasa, dagingnya dilumatkan dan dililitkan, bukan ditusuk.\",\"Batang serai memberi aroma tambahan saat sate dibakar.\"]', 'Unsplash / Sate Lilit Khas Bali');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('ayam-betutu', 'Ayam Betutu', 'Makanan', 'bali', 'Gilimanuk & Gianyar, Bali', 'Ayam atau bebek yang diisi bumbu basa genep, dibungkus daun, lalu dimasak lama hingga empuk dan meresap.', 'Betutu dikenal pedas, gurih, dan kaya rempah. Proses memasaknya yang lama membuat bumbu menyatu dengan dagingnya.', ' https://i.pinimg.com/736x/7f/b8/d9/7fb8d98cb1943e743d15374e2174ee97.jpg', '[{\"src\":\" https:\\/\\/i.pinimg.com\\/736x\\/7f\\/b8\\/d9\\/7fb8d98cb1943e743d15374e2174ee97.jpg\",\"caption\":\"Ayam Betutu - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ayam Betutu - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ayam Betutu - Warisan budaya luhur\"}]', '[\"Bumbu basa genep terdiri dari beragam rempah seperti kunyit, jahe, kencur, dan cabai.\",\"Hidangan ini sering disajikan dalam acara adat dan perayaan di Bali.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('babi-guling', 'Babi Guling', 'Makanan', 'bali', 'Bali', 'Babi panggang berbumbu rempah yang diputar di atas bara hingga kulitnya renyah dan dagingnya gurih.', 'Babi guling lekat dengan upacara adat dan perayaan masyarakat Bali Hindu. Perut babi diisi bumbu basa genep sebelum dipanggang perlahan.', ' https://blog.inivie.com/wp-content/uploads/2025/02/Artboard-13-20-1-1024x683.jpg', '[{\"src\":\" https:\\/\\/blog.inivie.com\\/wp-content\\/uploads\\/2025\\/02\\/Artboard-13-20-1-1024x683.jpg\",\"caption\":\"Babi Guling - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Babi Guling - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Babi Guling - Warisan budaya luhur\"}]', '[\"Kulit yang renyah dan bumbu rempah menjadi ciri khasnya.\",\"Hidangan ini biasa hadir pada upacara adat dan hari raya di Bali.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('endek-bali', 'Kain Endek', 'Pakaian', 'bali', 'Klungkung, Gianyar & Denpasar, Bali', 'Kain tenun ikat Bali dengan pola yang dibentuk dari benang pakan yang diikat dan dicelup sebelum ditenun.', 'Endek dibuat dengan teknik ikat pakan, sehingga motifnya terbentuk dari benang yang diwarnai bertahap. Kain ini dipakai untuk busana harian, seragam, hingga upacara.', ' https://down-id.img.susercontent.com/file/id-11134207-7ra0h-md2zyghhw8txaf', '[{\"src\":\" https:\\/\\/down-id.img.susercontent.com\\/file\\/id-11134207-7ra0h-md2zyghhw8txaf\",\"caption\":\"Kain Endek - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Kain Endek - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kain Endek - Warisan budaya luhur\"}]', '[\"Teknik ikat pakan berarti hanya benang pakan yang diikat dan diwarnai.\",\"Endek kini banyak dipadukan dengan desain busana modern.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('payas-agung', 'Payas Agung', 'Pakaian', 'bali', 'Bali', 'Busana pengantin kebesaran Bali dengan kain songket, mahkota emas, dan hiasan bunga yang mewah.', 'Payas Agung berasal dari busana kebangsawanan dan dipakai dalam upacara pernikahan adat. Busana ini terdiri dari kain songket, perhiasan emas, dan hiasan kepala yang penuh ornamen.', 'https://weddingmarket.com/storage/images/artikelideacontent/new/b5742c14b2951e6a759ecef6fbef2a55062c8dce.webp', '[{\"src\":\"https:\\/\\/weddingmarket.com\\/storage\\/images\\/artikelideacontent\\/new\\/b5742c14b2951e6a759ecef6fbef2a55062c8dce.webp\",\"caption\":\"Payas Agung - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Payas Agung - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Payas Agung - Warisan budaya luhur\"}]', '[\"Tata rias dan busana pengantin Bali dibedakan menurut tingkatan, seperti agung, madya, dan nista.\",\"Hiasan bunga emas pada mahkota menjadi daya tarik utamanya.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('udeng-kamen', 'Udeng & Kamen', 'Pakaian', 'bali', 'Bali', 'Busana adat ke pura berupa ikat kepala udeng, kain kamen, dan selendang saput.', 'Pria Bali mengenakan udeng, kamen, dan saput saat menghadiri upacara keagamaan sebagai bentuk kesopanan dan penghormatan. Cara melipat udeng pun memiliki makna.', ' https://down-id.img.susercontent.com/file/sg-11134201-22110-yprp3re844jv64', '[{\"src\":\" https:\\/\\/down-id.img.susercontent.com\\/file\\/sg-11134201-22110-yprp3re844jv64\",\"caption\":\"Udeng & Kamen - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Udeng & Kamen - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Udeng & Kamen - Warisan budaya luhur\"}]', '[\"Ujung udeng yang mengarah ke atas sering dimaknai sebagai pemusatan pikiran kepada Tuhan.\",\"Kamen adalah kain yang dililitkan di pinggang sebagai bawahan busana adat.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tari-kecak', 'Tari Kecak', 'Tradisi', 'bali', 'Uluwatu & Bona, Bali', 'Dramatari yang dibawakan puluhan pria bersila melingkar sambil menyerukan \"cak\" serempak, mengisahkan Ramayana.', 'Kecak berkembang dari ritual sanghyang yang bernuansa trans, lalu diperkaya dengan kisah Ramayana. Pertunjukannya di Uluwatu saat matahari terbenam menjadi daya tarik wisata terkenal.', 'https://cdn.ngopibareng.id/uploads/2022/2022-01-14/tari-kecak-merajut-asa-menuai-mimpi-pulihkan-wisata-di-bali--thumbnail-252', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1773563794845-b56cfaf0532a?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Lingkaran puluhan penari Kecak mengangkat kedua tangan ke angkasa di kala senja\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tokoh Hanoman Si Kera Putih beraksi di tengah lingkaran api\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Latar tebing laut Uluwatu yang dramatis dengan deburan ombak samudra Hindia\"}]', '[\"Tari ini tidak memakai gamelan; seluruh iringan berasal dari suara para penari.\",\"Kecak dalam bentuk pertunjukan seperti sekarang berkembang sekitar 1930-an.\"]', 'Unsplash / Tari Kecak Uluwatu');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('ngaben', 'Ngaben', 'Tradisi', 'bali', 'Bali', 'Upacara kremasi umat Hindu Bali untuk mengantarkan roh leluhur menuju alam berikutnya.', 'Ngaben dipandang sebagai penyucian dan pelepasan roh dari ikatan duniawi. Jenazah diarak dalam wadah atau bade dan kemudian dibakar dalam suasana yang penuh doa dan kebersamaan.', 'https://4.bp.blogspot.com/--FFfW6khOHU/UCZI2s7tfHI/AAAAAAAAAj0/Zzl7lxJtn6M/s1600/ngaben.jpg', '[{\"src\":\"https:\\/\\/4.bp.blogspot.com\\/--FFfW6khOHU\\/UCZI2s7tfHI\\/AAAAAAAAAj0\\/Zzl7lxJtn6M\\/s1600\\/ngaben.jpg\",\"caption\":\"Ngaben - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ngaben - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ngaben - Warisan budaya luhur\"}]', '[\"Bade adalah menara tandu yang mengusung jenazah menuju tempat kremasi.\",\"Ngaben bisa melibatkan banyak warga dan kerap dilakukan secara bersama-sama (ngaben massal).\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('nyepi', 'Nyepi & Ogoh-Ogoh', 'Tradisi', 'bali', 'Bali', 'Hari Raya Nyepi, tahun baru Saka, dirayakan dengan hening sehari penuh setelah arak-arakan ogoh-ogoh sehari sebelumnya.', 'Pada Nyepi, umat Hindu Bali menjalankan Catur Brata Penyepian: tidak menyalakan api, tidak bekerja, tidak bepergian, dan tidak bersenang-senang. Malam sebelumnya, ogoh-ogoh raksasa diarak lalu dibakar sebagai simbol penyucian.', 'https://cdn-1.timesmedia.co.id/images/2022/09/02/Hari-Raya-Nyepi-3.jpg', '[{\"src\":\"https:\\/\\/cdn-1.timesmedia.co.id\\/images\\/2022\\/09\\/02\\/Hari-Raya-Nyepi-3.jpg\",\"caption\":\"Nyepi & Ogoh-Ogoh - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Nyepi & Ogoh-Ogoh - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Nyepi & Ogoh-Ogoh - Warisan budaya luhur\"}]', '[\"Pada hari Nyepi, bandara internasional di Bali berhenti beroperasi selama sekitar 24 jam.\",\"Ogoh-ogoh dibuat secara gotong royong oleh pemuda banjar.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('soto-banjar', 'Soto Banjar', 'Makanan', 'kalimantan', 'Banjarmasin, Kalimantan Selatan', 'Soto ayam berkuah bening harum rempah dengan lontong atau ketupat, perkedel, dan telur rebus.', 'Soto Banjar memakai rempah seperti kayu manis, cengkih, dan pala yang membuat kuahnya wangi. Penyajiannya khas dengan soun, suwiran ayam, dan sambal.', 'https://media.tampang.com/tm_images/article/202411/buah-organikvpq8cjbb24h64gea.jpg', '[{\"src\":\"https:\\/\\/media.tampang.com\\/tm_images\\/article\\/202411\\/buah-organikvpq8cjbb24h64gea.jpg\",\"caption\":\"Soto Banjar - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Soto Banjar - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Soto Banjar - Warisan budaya luhur\"}]', '[\"Kuahnya bening tetapi sangat beraroma karena rempah utuh.\",\"Soto Banjar sering ditemani ketupat dan perkedel.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('juhu-singkah', 'Juhu Singkah', 'Makanan', 'kalimantan', 'Kalimantan Tengah', 'Masakan Dayak berbahan umbut rotan muda yang dimasak dengan ikan atau daging dan bumbu sederhana.', 'Juhu singkah memanfaatkan umbut rotan dari hutan sebagai bahan utama. Rasanya khas dengan sedikit pahit yang berpadu gurih kuah ikan atau ayam.', 'https://dimensiindonesia.com/wp-content/uploads/2025/11/Juhu-Singkah-scaled.jpg', '[{\"src\":\"https:\\/\\/dimensiindonesia.com\\/wp-content\\/uploads\\/2025\\/11\\/Juhu-Singkah-scaled.jpg\",\"caption\":\"Juhu Singkah - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Juhu Singkah - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Juhu Singkah - Warisan budaya luhur\"}]', '[\"Bahan utamanya diambil dari pucuk muda tanaman rotan.\",\"Hidangan ini mencerminkan cara masyarakat Dayak memanfaatkan hasil hutan.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('bubur-pedas-sambas', 'Bubur Pedas Sambas', 'Makanan', 'kalimantan', 'Sambas, Kalimantan Barat', 'Bubur nasi gurih dengan beragam sayuran dan dedaunan, kacang, dan teri, yang populer di bulan Ramadan.', 'Bubur pedas Sambas dimasak dengan campuran rempah, sayuran, dan daun-daunan sehingga beraroma kuat. Hidangan ini sangat lekat dengan tradisi berbuka puasa masyarakat Sambas.', 'https://assets.pikiran-rakyat.com/crop/0x0:0x0/x/photo/2021/10/03/3377290914.jpeg', '[{\"src\":\"https:\\/\\/assets.pikiran-rakyat.com\\/crop\\/0x0:0x0\\/x\\/photo\\/2021\\/10\\/03\\/3377290914.jpeg\",\"caption\":\"Bubur Pedas Sambas - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bubur Pedas Sambas - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bubur Pedas Sambas - Warisan budaya luhur\"}]', '[\"Bubur ini sering dibagikan kepada warga saat Ramadan.\",\"Aroma dan rasanya berasal dari aneka daun dan rempah lokal.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sasirangan', 'Kain Sasirangan', 'Pakaian', 'kalimantan', 'Banjarmasin, Kalimantan Selatan', 'Kain khas suku Banjar yang dihias dengan teknik jahit-jelujur dan ikat celup.', 'Nama sasirangan berasal dari kata menyirang, yakni menjahit jelujur kain sebelum dicelup. Hasilnya adalah motif warna-warni yang khas dan sarat makna.', 'https://down-id.img.susercontent.com/file/id-11134207-7r98o-lm4ok7j6udv8e1', '[{\"src\":\"https:\\/\\/down-id.img.susercontent.com\\/file\\/id-11134207-7r98o-lm4ok7j6udv8e1\",\"caption\":\"Kain Sasirangan - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Kain Sasirangan - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kain Sasirangan - Warisan budaya luhur\"}]', '[\"Pada awalnya kain ini digunakan dalam ritual pengobatan tradisional Banjar.\",\"Kini sasirangan dikembangkan menjadi busana, dekorasi, dan suvenir.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('baju-king-baba', 'Baju King Baba & King Bibinge', 'Pakaian', 'kalimantan', 'Kalimantan Barat', 'Busana adat Dayak berhias manik dan bulu burung, King Baba untuk pria dan King Bibinge untuk perempuan.', 'Busana ini dikenakan dalam upacara dan perayaan adat Dayak. Hiasan manik dan bulu menambah kesan gagah serta mencerminkan kekayaan alam Kalimantan.', 'https://asset-3s.3second.co.id/blog/image%20blog/1774882727.png', '[{\"src\":\"https:\\/\\/asset-3s.3second.co.id\\/blog\\/image%20blog\\/1774882727.png\",\"caption\":\"Baju King Baba & King Bibinge - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Baju King Baba & King Bibinge - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Baju King Baba & King Bibinge - Warisan budaya luhur\"}]', '[\"Bahan tradisionalnya diolah dari alam sekitar seperti kulit kayu dan serat.\",\"Manik-manik menjadi hiasan penting pada busana adat Dayak.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('manik-dayak', 'Manik-Manik Dayak', 'Pakaian', 'kalimantan', 'Kalimantan', 'Perhiasan dan hiasan busana dari manik-manik yang dirangkai dengan motif Dayak, sekaligus benda pusaka keluarga.', 'Manik dipakai pada kalung, ikat kepala, baju, hingga tas gendong. Manik-manik tua sering diwariskan antargenerasi dan dipercaya memiliki nilai spiritual.', 'https://asset-a.grid.id/crop/0x0:0x0/700x465/photo/2018/09/16/769367535.jpg', '[{\"src\":\"https:\\/\\/asset-a.grid.id\\/crop\\/0x0:0x0\\/700x465\\/photo\\/2018\\/09\\/16\\/769367535.jpg\",\"caption\":\"Manik-Manik Dayak - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Manik-Manik Dayak - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Manik-Manik Dayak - Warisan budaya luhur\"}]', '[\"Manik-manik lama diwariskan sebagai pusaka keluarga.\",\"Motif manik umumnya terinspirasi flora, fauna, dan kepercayaan Dayak.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tari-hudoq', 'Tari Hudoq', 'Tradisi', 'kalimantan', 'Kalimantan Timur', 'Tarian bertopeng suku Dayak yang dilakukan pada awal musim tanam untuk memohon panen yang baik.', 'Penari memakai topeng kayu berwujud burung atau makhluk mitos dan kostum dari dedaunan. Gerakan mereka melambangkan roh pelindung yang menjaga ladang dari hama.', 'https://3.bp.blogspot.com/-a02h_MnxtKE/WcEAAtPgejI/AAAAAAAA4aE/34-bGCsoSkAW62YE_j0Tjer-uDKSfkspgCEwYBhgL/s1600/Hudoq4.JPG', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Penari Hudoq bertopeng kayu dan berbalut rimbun dedaunan pisang\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ritual tarian di halaman desa Dayak diiringi tabuhan gong dan tubun\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Detail ukiran topeng sakral Hudoq dengan taring kayu khas\"}]', '[\"Tarian ini berkaitan erat dengan siklus bercocok tanam padi.\",\"Topeng dan kostum dedaunan membuat penari tampil sebagai roh pelindung.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('erau-kutai', 'Erau Kutai', 'Tradisi', 'kalimantan', 'Tenggarong, Kalimantan Timur', 'Pesta adat Kesultanan Kutai Kartanegara dengan ritual mengulur naga dan belimbur, saling siram air.', 'Erau berarti ramai atau riuh, dan menjadi perayaan besar budaya Kutai. Rangkaian acaranya meliputi upacara adat, pertunjukan seni, dan ritual yang melibatkan masyarakat luas.', 'https://media.suara.com/pictures/970x544/2023/09/20/83098-perayaan-erau-di-kukar-ist.jpg', '[{\"src\":\"https:\\/\\/media.suara.com\\/pictures\\/970x544\\/2023\\/09\\/20\\/83098-perayaan-erau-di-kukar-ist.jpg\",\"caption\":\"Erau Kutai - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Erau Kutai - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Erau Kutai - Warisan budaya luhur\"}]', '[\"Salah satu puncaknya adalah ritual mengulur naga di Sungai Mahakam.\",\"Belimbur adalah tradisi saling menyiram air di penghujung acara.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tiwah', 'Tiwah', 'Tradisi', 'kalimantan', 'Kalimantan Tengah', 'Upacara ritual kematian tingkat akhir masyarakat Dayak Ngaju penganut Kaharingan untuk mengantar roh ke alam leluhur.', 'Dalam Tiwah, tulang belulang leluhur dipindahkan ke sandung sebagai tempat peristirahatan terakhir. Upacara ini berlangsung beberapa hari dan melibatkan keluarga besar serta masyarakat.', 'https://betv.disway.id/upload/4e1d105e7c0020b46c3aa3291a5b4563.jpeg', '[{\"src\":\"https:\\/\\/betv.disway.id\\/upload\\/4e1d105e7c0020b46c3aa3291a5b4563.jpeg\",\"caption\":\"Tiwah - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tiwah - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tiwah - Warisan budaya luhur\"}]', '[\"Sandung adalah bangunan kecil tempat menyimpan tulang leluhur.\",\"Upacara ini dapat memakan waktu beberapa hari dan biaya besar sehingga sering diadakan bersama-sama.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('coto-makassar', 'Coto Makassar', 'Makanan', 'sulawesi', 'Makassar, Sulawesi Selatan', 'Sup daging dan jeroan sapi berkuah kental gurih dari kacang tanah dan puluhan rempah.', 'Coto disantap bersama ketupat dan sambal, menjadi sarapan favorit warga Makassar. Kuahnya pekat dengan aroma rempah dan kacang yang kuat.', 'https://i.pinimg.com/1200x/11/c3/4c/11c34c5fc5b213459af3b0de9cfa0224.jpg', '[{\"src\":\"https:\\/\\/kediripedia.com\\/wp-content\\/uploads\\/2020\\/01\\/sate-padang-1024x683.jpg\",\"caption\":\"Semangkuk Coto Makassar kuah kacang kental dengan taburan daun bawang dan seledri\"},{\"src\":\"https:\\/\\/www.jamrocksportsbarandgrill.com\\/wp-content\\/uploads\\/2026\\/02\\/Proses-Pembuatan-Rendang-Tradisional-yang-Kaya-Rempah-788x520.jpg\",\"caption\":\"Penyajian dengan ketupat daun kelapa potong dan sambal taoco pedas\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Rebusan daging sapi dalam kuali tanah liat besar beraroma rempah wangi\"}]', '[\"Kuahnya dikentalkan dengan kacang tanah sangrai yang digiling.\",\"Coto biasa dimakan dengan ketupat atau burasa.\"]', 'Unsplash / Coto Makassar Khas Sulsel');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('konro', 'Konro', 'Makanan', 'sulawesi', 'Makassar, Sulawesi Selatan', 'Iga sapi berkuah cokelat gelap dari kluwek, tersedia juga versi bakar dengan olesan bumbu manis.', 'Konro berkuah hitam kecokelatan dengan rasa gurih rempah. Versi konro bakar disajikan tanpa kuah, dibakar dan dilumuri bumbu, dimakan dengan sambal dan nasi atau ketupat.', 'https://i.pinimg.com/736x/40/d5/89/40d5893e63b4881706aac244021e520a.jpg', '[{\"src\":\"https:\\/\\/i.pinimg.com\\/736x\\/40\\/d5\\/89\\/40d5893e63b4881706aac244021e520a.jpg\",\"caption\":\"Konro - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Konro - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Konro - Warisan budaya luhur\"}]', '[\"Warna gelap kuahnya berasal dari kluwek.\",\"Iga sapi menjadi bahan utama sehingga dagingnya empuk dan berlemak.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tinutuan', 'Tinutuan (Bubur Manado)', 'Makanan', 'sulawesi', 'Manado, Sulawesi Utara', 'Bubur nasi dengan labu kuning, singkong, jagung, bayam, dan kemangi, disantap dengan ikan asin dan sambal dabu-dabu.', 'Tinutuan adalah sarapan khas Manado yang kaya sayuran. Rasanya ringan dan gurih, dilengkapi sambal dabu-dabu yang segar pedas.', 'https://i.pinimg.com/736x/81/77/ba/8177bab14663abb71bd3b6228027e91e.jpg', '[{\"src\":\"https:\\/\\/i.pinimg.com\\/736x\\/81\\/77\\/ba\\/8177bab14663abb71bd3b6228027e91e.jpg\",\"caption\":\"Tinutuan (Bubur Manado) - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tinutuan (Bubur Manado) - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tinutuan (Bubur Manado) - Warisan budaya luhur\"}]', '[\"Tinutuan dimasak dengan beragam sayuran dan umbi sehingga bergizi.\",\"Sambal dabu-dabu dan ikan asin adalah teman makan yang lazim.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('baju-bodo', 'Baju Bodo', 'Pakaian', 'sulawesi', 'Sulawesi Selatan', 'Busana tradisional perempuan Bugis-Makassar berpotongan persegi dan bahan tipis, dipadukan dengan sarung sutra.', 'Baju bodo dikenal sebagai salah satu pakaian tradisional tertua di Nusantara. Warna yang dikenakan dapat menandakan usia atau kedudukan pemakainya.', 'https://i.pinimg.com/474x/be/59/e0/be59e0410da33d2059e188082d6e91f6.jpg', '[{\"src\":\"https:\\/\\/i.pinimg.com\\/474x\\/be\\/59\\/e0\\/be59e0410da33d2059e188082d6e91f6.jpg\",\"caption\":\"Baju Bodo - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Baju Bodo - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Baju Bodo - Warisan budaya luhur\"}]', '[\"Warna baju bodo menandakan kelompok usia dan status sosial.\",\"Pakaian ini biasanya dikenakan dalam upacara adat dan pernikahan.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sutra-sengkang', 'Sutra Sengkang', 'Pakaian', 'sulawesi', 'Sengkang, Wajo, Sulawesi Selatan', 'Sarung sutra tenunan tangan khas Bugis dari Sengkang yang halus dan berkilau.', 'Sengkang dikenal sebagai sentra sutra, dengan sarung sutra yang disebut lipa sabbe. Kain ini ditenun dengan motif kotak-kotak khas dan dipakai dalam acara adat.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTkpp4fp7tWG9l-nOZ8CcPzkD1KDWCcsvDFmuOwd-QnoPnm8W_anGjgi3kN&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcTkpp4fp7tWG9l-nOZ8CcPzkD1KDWCcsvDFmuOwd-QnoPnm8W_anGjgi3kN&s=10\",\"caption\":\"Sutra Sengkang - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Sutra Sengkang - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Sutra Sengkang - Warisan budaya luhur\"}]', '[\"Sarung sutra Bugis dikenal dengan sebutan lipa sabbe.\",\"Sengkang di Kabupaten Wajo terkenal sebagai pusat persuteraan.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tenun-sadan', 'Tenun Sa’dan Toraja', 'Pakaian', 'sulawesi', 'Toraja, Sulawesi Selatan', 'Tenun tradisional Toraja bermotif geometris yang ditenun dengan alat tenun gedogan.', 'Motif tenun Sa’dan terinspirasi dari alam dan ukiran Toraja, dengan warna-warna yang bernuansa sakral. Kain ini dipakai dalam upacara adat dan sebagai hiasan.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTNnZhfiiIGd0lU1bw8qsfm2Gu1j6D3dv0MM_9NceA9D5GXdA5brkX9GYg&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcTNnZhfiiIGd0lU1bw8qsfm2Gu1j6D3dv0MM_9NceA9D5GXdA5brkX9GYg&s=10\",\"caption\":\"Tenun Sa’dan Toraja - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tenun Sa’dan Toraja - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Tenun Sa’dan Toraja - Warisan budaya luhur\"}]', '[\"Tenun Sa’dan dikerjakan dengan alat tenun tradisional gedogan.\",\"Pola geometrisnya sering terhubung dengan motif ukiran Toraja.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('rambu-solo', 'Rambu Solo', 'Tradisi', 'sulawesi', 'Tana Toraja, Sulawesi Selatan', 'Upacara pemakaman adat Toraja yang megah untuk mengantarkan arwah menuju alam leluhur.', 'Rambu Solo dipandang sebagai kewajiban keluarga terhadap yang meninggal dan berlangsung beberapa hari. Rangkaiannya mencakup pengorbanan kerbau, tarian, dan prosesi adat.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT_iEOcr8py88bx2zbJhYVElzf6KuVDYnvogeeyeN8Rzw&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcT_iEOcr8py88bx2zbJhYVElzf6KuVDYnvogeeyeN8Rzw&s=10\",\"caption\":\"Rambu Solo - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Rambu Solo - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Rambu Solo - Warisan budaya luhur\"}]', '[\"Kerbau menjadi lambang status dan bagian penting dalam upacara.\",\"Keluarga dapat menyimpan jenazah lebih lama sambil menyiapkan upacara besar.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('pembuatan-pinisi', 'Seni Pembuatan Perahu Pinisi', 'Tradisi', 'sulawesi', 'Bulukumba, Sulawesi Selatan', 'Tradisi membuat kapal layar pinisi oleh pengrajin Bugis-Makassar di Bulukumba dengan ritual dan keahlian turun-temurun.', 'Pembuatan pinisi disertai ritual, mulai dari menentukan hari baik hingga peluncuran kapal. Keahlian ini diwariskan lintas generasi tanpa gambar teknik tertulis.', 'https://awsimages.detik.net.id/community/media/visual/2023/11/21/awal-mula-bulukumba-jadi-pusat-pembuatan-kapal-pinisi-sejak-abad-15-1.jpeg?w=800', '[{\"src\":\"https:\\/\\/awsimages.detik.net.id\\/community\\/media\\/visual\\/2023\\/11\\/21\\/awal-mula-bulukumba-jadi-pusat-pembuatan-kapal-pinisi-sejak-abad-15-1.jpeg?w=800\",\"caption\":\"Seni Pembuatan Perahu Pinisi - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Seni Pembuatan Perahu Pinisi - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Seni Pembuatan Perahu Pinisi - Warisan budaya luhur\"}]', '[\"UNESCO mengakui seni pembuatan perahu pinisi di Sulawesi Selatan sebagai warisan budaya takbenda pada 2017.\",\"Pinisi dikenal dengan dua tiang layar utama dan tujuh layar.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tari-pakarena', 'Tari Pakarena', 'Tradisi', 'sulawesi', 'Gowa, Sulawesi Selatan', 'Tarian perempuan Makassar yang lemah gemulai, diiringi gendang dan alat tiup tradisional.', 'Pakarena menampilkan gerak lembut dan pelan yang mencerminkan kesantunan perempuan Makassar. Tarian ini awalnya dipentaskan di lingkungan istana dan kini menjadi kebanggaan daerah.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSlcX9jMx_jg6lJLOpjykNO2DXig8D4EYG_kS9NFOtQFA&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcSlcX9jMx_jg6lJLOpjykNO2DXig8D4EYG_kS9NFOtQFA&s=10\",\"caption\":\"Tari Pakarena - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tari Pakarena - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tari Pakarena - Warisan budaya luhur\"}]', '[\"Gerakan tarian yang lambat melambangkan kesopanan dan kehalusan budi.\",\"Iringan musiknya memakai gendang dan alat tiup khas Makassar.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('ayam-taliwang', 'Ayam Taliwang', 'Makanan', 'nusa-tenggara', 'Mataram, Lombok', 'Ayam kampung bakar berbumbu cabai dan terasi yang pedas, kuliner ikonik Lombok.', 'Ayam taliwang dibakar dengan bumbu pedas khas Sasak, biasanya disajikan bersama plecing kangkung. Rasanya pedas, gurih, dan beraroma bakaran.', 'https://d1uz88p17r663j.cloudfront.net/original/c9083eee3069c0ddf0a6ce11ef8567a9_AyamBakar.jpg', '[{\"src\":\"https:\\/\\/d1uz88p17r663j.cloudfront.net\\/original\\/c9083eee3069c0ddf0a6ce11ef8567a9_AyamBakar.jpg\",\"caption\":\"Ayam Taliwang - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ayam Taliwang - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ayam Taliwang - Warisan budaya luhur\"}]', '[\"Namanya dikaitkan dengan kawasan Karang Taliwang di Mataram.\",\"Plecing kangkung adalah pendamping yang lazim.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sei-sapi', 'Se’i Sapi', 'Makanan', 'nusa-tenggara', 'Kupang, Nusa Tenggara Timur', 'Daging asap khas Timor yang diasap dengan kayu kosambi hingga empuk dan beraroma khas.', 'Se’i berarti daging yang diiris dan diasapi, dan di NTT umumnya dibuat dari daging sapi atau babi. Pengasapan memberi aroma dan rasa gurih yang khas, dinikmati dengan sambal luat.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRfa4EkP93hmWjx9YdKYf_npdcPOeWrbuGbIb8-9MadlQZHEhBMl0gYO8sZ&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcRfa4EkP93hmWjx9YdKYf_npdcPOeWrbuGbIb8-9MadlQZHEhBMl0gYO8sZ&s=10\",\"caption\":\"Se’i Sapi - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Se’i Sapi - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Se’i Sapi - Warisan budaya luhur\"}]', '[\"Kayu kosambi dipakai untuk mengasapi dan memberi aroma khas.\",\"Se’i dinikmati bersama sambal luat dan nasi.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('jagung-bose', 'Jagung Bose', 'Makanan', 'nusa-tenggara', 'Timor, Nusa Tenggara Timur', 'Hidangan jagung pipil yang ditumbuk lalu dimasak dengan santan, kacang, dan labu, makanan pokok masyarakat Timor.', 'Jagung bose mencerminkan kebiasaan makan masyarakat Timor yang bertumpu pada jagung. Teksturnya lembut dan gurih, cocok disantap bersama lauk ikan atau daging.', 'https://www.indonesia.travel/contentassets/32348301b31049bf8a9952a06bbc3294/jagung-bose.jpg', '[{\"src\":\"https:\\/\\/www.indonesia.travel\\/contentassets\\/32348301b31049bf8a9952a06bbc3294\\/jagung-bose.jpg\",\"caption\":\"Jagung Bose - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Jagung Bose - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Jagung Bose - Warisan budaya luhur\"}]', '[\"Jagung adalah makanan pokok penting di banyak wilayah NTT.\",\"Proses menumbuk jagung menjadi bagian dari tradisi dapur masyarakat Timor.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tenun-ikat', 'Tenun Ikat Sumba', 'Pakaian', 'nusa-tenggara', 'Sumba, Nusa Tenggara Timur', 'Kain tenun ikat dengan motif kuda, ayam, dan manusia yang diwarnai pewarna alami dalam proses panjang.', 'Tenun ikat Sumba memiliki makna adat dan spiritual, dipakai dalam upacara kelahiran, pernikahan, hingga pemakaman. Pewarna alaminya berasal dari akar dan daun tanaman.', 'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80', '[{\"src\":\"https:\\/\\/blogger.googleusercontent.com\\/img\\/b\\/R29vZ2xl\\/AVvXsEh-SVgko2JTImRwC-3dGIE_3V2WjQDWi7UenMIhf0SnGo1CmJttJpxxnV_hwox08fANXpSsoel0tv8TE_aAoA78rFTVnMoAuE81Fy1IbGc-1gnbvt3CXADlaPPYzqjppkYJ0hauREqYDMQ\\/s1600\\/Industri-Batik-Hadapi-MEA-271015-Prad-1.jpg\",\"caption\":\"Corak motif kuda dan burung kakatua pada kain Tenun Ikat Sumba Timur\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=1200&auto=format&fit=crop\",\"caption\":\"Mama-mama Sumba mengikat pola benang kapas sebelum proses celup warna alami\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1544816155-12df9643f363?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pameran kain tenun ikat pusaka di kampung adat Prai Ijing Sumba\"}]', '[\"Warna merah umumnya berasal dari akar mengkudu dan biru dari tanaman nila.\",\"Selembar kain berkualitas tinggi bisa memakan waktu berbulan-bulan hingga setahun.\"]', 'Unsplash / Tenun Ikat Sumba NTT');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('songket-lombok', 'Songket Lombok (Sukarara)', 'Pakaian', 'nusa-tenggara', 'Sukarara, Lombok Tengah', 'Songket tenun tangan Sasak dengan motif geometris dan benang emas, terkenal dari Desa Sukarara.', 'Di Sukarara, menenun songket menjadi keterampilan yang diwariskan kepada anak perempuan. Kain ini dipakai dalam upacara adat dan pernikahan Sasak.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRi8jGHKF5MT0ENeRF372L1y-TbeVrhHeBdMe3bvpAjOw&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcRi8jGHKF5MT0ENeRF372L1y-TbeVrhHeBdMe3bvpAjOw&s=10\",\"caption\":\"Songket Lombok (Sukarara) - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Songket Lombok (Sukarara) - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Songket Lombok (Sukarara) - Warisan budaya luhur\"}]', '[\"Menenun dipandang sebagai keterampilan penting bagi perempuan Sasak.\",\"Desa Sukarara kini menjadi tujuan wisata belajar menenun.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('ti-i-langga', 'Topi Ti’i Langga', 'Pakaian', 'nusa-tenggara', 'Rote Ndao, Nusa Tenggara Timur', 'Topi anyaman daun lontar dari Pulau Rote dengan hiasan mencuat di bagian atasnya.', 'Ti’i langga dibuat dari daun lontar yang dianyam dan dikenakan pria Rote dalam upacara serta acara adat. Bentuknya yang khas menjadi ikon budaya Rote.', 'https://pdbifiles.nos.jkt-1.neo.id/files/2014/06/24/roby08darisandi_tiilangga.jpg', '[{\"src\":\"https:\\/\\/pdbifiles.nos.jkt-1.neo.id\\/files\\/2014\\/06\\/24\\/roby08darisandi_tiilangga.jpg\",\"caption\":\"Topi Ti’i Langga - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Topi Ti’i Langga - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Topi Ti’i Langga - Warisan budaya luhur\"}]', '[\"Bahan utamanya adalah daun lontar, tanaman khas Rote.\",\"Bentuknya yang khas dengan bagian atas mencuat mudah dikenali sebagai ikon NTT.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('pasola-sumba', 'Pasola', 'Tradisi', 'nusa-tenggara', 'Sumba Barat, Nusa Tenggara Timur', 'Ritual adat penganut Marapu: dua kelompok penunggang kuda saling melempar tombak kayu di lapangan terbuka.', 'Pasola digelar setiap tahun bertepatan dengan musim nyale sekitar Februari-Maret. Tradisi ini dipercaya memohon kesuburan tanah dan hasil panen, dibuka dengan ritual adat.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRCK8Vwh9RXSbU8EPEVLVkKRoEh8REKb0wrnhp6gH_ZfA&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcRCK8Vwh9RXSbU8EPEVLVkKRoEh8REKb0wrnhp6gH_ZfA&s=10\",\"caption\":\"Pasola - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pasola - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pasola - Warisan budaya luhur\"}]', '[\"Tombak yang dilempar terbuat dari kayu dan tumpul.\",\"Waktu pelaksanaannya mengikuti kemunculan cacing laut nyale.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('caci-manggarai', 'Caci', 'Tradisi', 'nusa-tenggara', 'Manggarai, Flores', 'Pertunjukan adu ketangkasan dua pria Manggarai: satu memecut dengan cambuk, satu menangkis dengan perisai.', 'Caci biasanya dipentaskan pada perayaan syukur panen seperti Penti. Para peserta mengenakan busana adat dan topi bertanduk, diiringi nyanyian dan gong.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRJ3ZxoXngjaJrnrijH6rWLM1SjVhX9JyXJ92sEBpSotg&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcRJ3ZxoXngjaJrnrijH6rWLM1SjVhX9JyXJ92sEBpSotg&s=10\",\"caption\":\"Caci - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Caci - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Caci - Warisan budaya luhur\"}]', '[\"Cambuk disebut larik, sedangkan perisainya disebut nggiling.\",\"Pertunjukan ini identik dengan perayaan syukur panen.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('bau-nyale', 'Bau Nyale', 'Tradisi', 'nusa-tenggara', 'Lombok Tengah, Nusa Tenggara Barat', 'Tradisi menangkap cacing laut nyale di pantai pada waktu tertentu setiap tahun, terkait legenda Putri Mandalika.', 'Warga berbondong-bondong ke pantai selatan Lombok pada malam tertentu untuk menangkap nyale. Tradisi ini diyakini terkait kisah Putri Mandalika yang menceburkan diri ke laut.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQc9AOZkfeTjINj_AlJe-wYLqO0V3NIxqYnF57xEjP3pGk7FyGKMD9IDTWs&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcQc9AOZkfeTjINj_AlJe-wYLqO0V3NIxqYnF57xEjP3pGk7FyGKMD9IDTWs&s=10\",\"caption\":\"Bau Nyale - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bau Nyale - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bau Nyale - Warisan budaya luhur\"}]', '[\"Nyale muncul pada waktu tertentu, biasanya sekitar Februari-Maret.\",\"Legenda Putri Mandalika menjadi latar kisah tradisi ini.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('papeda', 'Papeda & Ikan Kuah Kuning', 'Makanan', 'maluku', 'Maluku', 'Bubur sagu kenyal yang disantap bersama ikan berkuah kuning dari kunyit dan jeruk nipis.', 'Papeda adalah makanan pokok masyarakat Maluku dan Papua yang terbuat dari pati sagu. Kuah kuning ikan yang segar asam menjadi pasangan yang pas.', 'https://papeda.ambon.go.id/storage/2025/11/Papeda-ikan-kuah-kuning.jpg', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Papeda kenyal bening disajikan bersama sup ikan kuah kuning berempah\"},{\"src\":\"https:\\/\\/kediripedia.com\\/wp-content\\/uploads\\/2020\\/01\\/sate-padang-1024x683.jpg\",\"caption\":\"Teknik menggulung papeda dari mangkuk gerabah menggunakan gata-gata\"},{\"src\":\"https:\\/\\/www.jamrocksportsbarandgrill.com\\/wp-content\\/uploads\\/2026\\/02\\/Proses-Pembuatan-Rendang-Tradisional-yang-Kaya-Rempah-788x520.jpg\",\"caption\":\"Olahan ikan cakalang bumbu kuning segar khas laut banda\"}]', '[\"Papeda biasanya dimakan dengan cara dililit memakai sumpit atau garpu lalu ditaruh ke piring.\",\"Sagu telah menjadi sumber pangan penting di Indonesia Timur sejak lama.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('kohu-kohu', 'Kohu-Kohu', 'Makanan', 'maluku', 'Ambon, Maluku', 'Salad ikan khas Maluku dengan kelapa parut, tauge, kemangi, dan perasan jeruk.', 'Kohu-kohu menyajikan ikan segar yang diolah ringan bersama sayuran dan kelapa. Rasanya segar, asam, dan pedas.', 'https://asset.tribunnews.com/VXP5VynuVkiuz3ue9jVEQmyNJNo=/1200x675/filters:upscale():quality(30):format(webp):focal(0.5x0.5:0.5x0.5)/medan/foto/bank/originals/Resep-Kohu-Kohu-dan-Cara-Membuatnya.jpg', '[{\"src\":\"https:\\/\\/asset.tribunnews.com\\/VXP5VynuVkiuz3ue9jVEQmyNJNo=\\/1200x675\\/filters:upscale():quality(30):format(webp):focal(0.5x0.5:0.5x0.5)\\/medan\\/foto\\/bank\\/originals\\/Resep-Kohu-Kohu-dan-Cara-Membuatnya.jpg\",\"caption\":\"Kohu-Kohu - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kohu-Kohu - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kohu-Kohu - Warisan budaya luhur\"}]', '[\"Kelapa parut dan kemangi memberi aroma segar khas Maluku.\",\"Hidangan ini cocok disantap bersama papeda atau nasi.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('sagu-lempeng', 'Sagu Lempeng', 'Makanan', 'maluku', 'Maluku', 'Sagu panggang berbentuk lempengan keras yang tahan lama, dinikmati dengan teh, kopi, atau sup.', 'Sagu dicetak dalam cetakan tanah liat lalu dipanggang hingga mengeras. Lempeng ini awet disimpan dan biasa dicelup ke minuman hangat atau kuah.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTS6D7tbS8Fsq4swmWYuTS4mpKE1dzc0zf5YsrhynAnPQ&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcTS6D7tbS8Fsq4swmWYuTS4mpKE1dzc0zf5YsrhynAnPQ&s=10\",\"caption\":\"Sagu Lempeng - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Sagu Lempeng - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Sagu Lempeng - Warisan budaya luhur\"}]', '[\"Teksturnya keras sehingga biasanya dicelup sebelum dimakan.\",\"Sagu lempeng dapat disimpan lama sebagai bekal.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('baju-cele', 'Baju Cele', 'Pakaian', 'maluku', 'Ambon, Maluku', 'Busana tradisional Maluku berupa baju longgar bercorak cerah yang dipadukan dengan kain tradisional.', 'Baju cele dikenakan pada acara adat dan perayaan sebagai identitas Maluku. Warna-warna cerahnya mencerminkan keceriaan masyarakat pesisir.', 'https://radarmukomuko.disway.id/upload/0b4de64d01ef6182a28d74db7557976e.jpg', '[{\"src\":\"https:\\/\\/radarmukomuko.disway.id\\/upload\\/0b4de64d01ef6182a28d74db7557976e.jpg\",\"caption\":\"Baju Cele - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Baju Cele - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Baju Cele - Warisan budaya luhur\"}]', '[\"Busana ini sering dipakai pada acara adat dan penyambutan tamu.\",\"Warna cerahnya menggambarkan kehangatan masyarakat Maluku.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tenun-tanimbar', 'Tenun Ikat Tanimbar', 'Pakaian', 'maluku', 'Kepulauan Tanimbar, Maluku', 'Tenun ikat Kepulauan Tanimbar bermotif geometris dan flora fauna, dipakai dalam upacara adat.', 'Tenun Tanimbar dibuat dengan teknik ikat dan pewarna alami. Kain ini punya peran dalam upacara adat dan sebagai benda berharga dalam pertukaran adat.', 'https://awsimages.detik.net.id/community/media/visual/2022/10/10/jokowi-mengenakan-kain-khas-tanimbar-1_169.jpeg?w=1200', '[{\"src\":\"https:\\/\\/awsimages.detik.net.id\\/community\\/media\\/visual\\/2022\\/10\\/10\\/jokowi-mengenakan-kain-khas-tanimbar-1_169.jpeg?w=1200\",\"caption\":\"Tenun Ikat Tanimbar - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tenun Ikat Tanimbar - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tenun Ikat Tanimbar - Warisan budaya luhur\"}]', '[\"Kain ini dipakai dalam upacara adat dan pertukaran adat.\",\"Motifnya terinspirasi dari alam dan kepercayaan setempat.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('lenso', 'Lenso', 'Pakaian', 'maluku', 'Maluku', 'Sapu tangan berwarna cerah yang menjadi aksesori khas tarian dan pergaulan masyarakat Maluku.', 'Lenso dipakai penari dan sering dilambaikan dalam tarian pergaulan. Aksesori ini menjadi simbol keramahan dan keceriaan dalam budaya Maluku.', 'https://down-id.img.susercontent.com/file/id-11134207-7qul5-ljxx3cjp6hj73c', '[{\"src\":\"https:\\/\\/down-id.img.susercontent.com\\/file\\/id-11134207-7qul5-ljxx3cjp6hj73c\",\"caption\":\"Lenso - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Lenso - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Lenso - Warisan budaya luhur\"}]', '[\"Lenso identik dengan tarian pergaulan Maluku.\",\"Warna dan cara menggunakannya menambah keceriaan pertunjukan.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tari-cakalele', 'Tari Cakalele', 'Tradisi', 'maluku', 'Kepulauan Maluku', 'Tarian perang Maluku dengan parang dan salawaku (perisai), diiringi tifa dan teriakan semangat.', 'Cakalele ditarikan para pria berpakaian merah dan ikat kepala, menggambarkan keberanian prajurit. Tarian ini sering dibawakan dalam penyambutan tamu dan upacara adat.', 'https://image.idn.media/post/20230313/0413232022-shutterstock-1483726541-4ca10d321848f1c96b9086e0d4cbfff3.jpg', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Prajurit Cakalele memegang parang dan salawaku dengan tatapan tajam berani\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Gerakan loncatan dinamis menghentak bumi mengelilingi api unggun\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tabuhan tifa berdentum mengiringi teriakan pekik perang adat\"}]', '[\"Salawaku adalah perisai kayu yang menjadi perlengkapan penari.\",\"Tifa dan gong mengiringi gerakan yang dinamis dan penuh semangat.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('pela-gandong', 'Pela Gandong', 'Tradisi', 'maluku', 'Pulau Ambon & Lease, Maluku', 'Ikatan persaudaraan adat antar-negeri (desa) di Maluku yang diikrarkan lewat sumpah dan saling tolong-menolong.', 'Pela adalah perjanjian persaudaraan antar desa, sedangkan gandong berarti kakak-adik. Tradisi ini menjadi perekat sosial yang menjembatani perbedaan, termasuk lintas agama.', 'https://www.harapanrakyat.com/wp-content/uploads/2025/01/Mengenal-Tradisi-Sejarah-Pela-Gandong-di-Maluku.jpg', '[{\"src\":\"https:\\/\\/www.harapanrakyat.com\\/wp-content\\/uploads\\/2025\\/01\\/Mengenal-Tradisi-Sejarah-Pela-Gandong-di-Maluku.jpg\",\"caption\":\"Pela Gandong - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pela Gandong - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Pela Gandong - Warisan budaya luhur\"}]', '[\"Pela Gandong berfungsi sebagai ikatan tolong-menolong antar desa.\",\"Nilai persaudaraannya sering dihidupkan kembali sebagai perekat perdamaian.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('bambu-gila', 'Bambu Gila', 'Tradisi', 'maluku', 'Maluku', 'Pertunjukan ritual ketika sebatang bambu bergerak liar dan sulit ditahan beberapa orang setelah dibacakan doa oleh pawang.', 'Bambu gila dibuka dengan doa dan asap kemenyan oleh sang pawang. Bambu kemudian bergerak kuat dan para pemainnya berusaha menahannya, menjadi tontonan yang menegangkan.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQjq6nUU5pyrlRz0Gz-hjvWSwdSlXNJ6L65Gj388OSMPCsyngG7w-CC6yU&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcQjq6nUU5pyrlRz0Gz-hjvWSwdSlXNJ6L65Gj388OSMPCsyngG7w-CC6yU&s=10\",\"caption\":\"Bambu Gila - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bambu Gila - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bambu Gila - Warisan budaya luhur\"}]', '[\"Pawang memimpin doa dan ritual sebelum bambu dimainkan.\",\"Beberapa orang harus bekerja sama untuk menahan gerak bambu.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('papeda-papua', 'Papeda Papua', 'Makanan', 'papua', 'Papua', 'Bubur sagu kenyal yang menjadi makanan pokok Papua, disantap dengan ikan berkuah kuning.', 'Di Papua, sagu merupakan sumber pangan pokok bagi banyak komunitas. Papeda disantap bersama kuah ikan segar yang gurih asam.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Papeda%2C_Kuah_Kuning%2C_Ikan_Tude_Bakar_2.jpg/1280px-Papeda%2C_Kuah_Kuning%2C_Ikan_Tude_Bakar_2.jpg?utm_source=id.wikipedia.org&utm_campaign=index&utm_content=thumbnail', '[{\"src\":\"https:\\/\\/thumb.wikimedia.org\\/wikipedia\\/commons\\/thumb\\/0\\/01\\/Papeda%2C_Kuah_Kuning%2C_Ikan_Tude_Bakar_2.jpg\\/1280px-Papeda%2C_Kuah_Kuning%2C_Ikan_Tude_Bakar_2.jpg?utm_source=id.wikipedia.org&utm_campaign=index&utm_content=thumbnail\",\"caption\":\"Papeda Papua - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Papeda Papua - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Papeda Papua - Warisan budaya luhur\"}]', '[\"Sagu dipanen dari batang pohon sagu yang tumbuh di rawa.\",\"Papeda biasanya disajikan panas dan dimakan bersama ikan berkuah.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('ulat-sagu', 'Ulat Sagu', 'Makanan', 'papua', 'Papua', 'Larva kumbang yang hidup di batang sagu dan dinikmati mentah, dibakar, atau ditumis sebagai sumber protein.', 'Ulat sagu merupakan makanan tradisional di beberapa komunitas di Papua, seperti suku Asmat dan Kamoro. Gizinya tinggi dan biasa diolah dengan cara sederhana.', 'https://media.sukabumiupdate.com/media/2023/02/16/1676558256_63ee3fb010c0d_87fkGAhGjdnTPMSkOWoK.jpg', '[{\"src\":\"https:\\/\\/media.sukabumiupdate.com\\/media\\/2023\\/02\\/16\\/1676558256_63ee3fb010c0d_87fkGAhGjdnTPMSkOWoK.jpg\",\"caption\":\"Ulat Sagu - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ulat Sagu - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Ulat Sagu - Warisan budaya luhur\"}]', '[\"Ulat sagu hidup di batang pohon sagu yang membusuk.\",\"Kaya protein, sehingga menjadi sumber gizi penting di beberapa komunitas.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('udang-selingkuh', 'Udang Selingkuh', 'Makanan', 'papua', 'Merauke, Papua Selatan', 'Udang air tawar khas Merauke bercapit mirip kepiting, bercita rasa manis dan gurih.', 'Udang selingkuh dinamai demikian karena bentuknya yang tampak perpaduan udang dan kepiting. Hidangan ini diolah dengan digoreng, direbus, atau dibakar.', 'https://rricoid-assets.obs.ap-southeast-4.myhuaweicloud.com/berita/Biak/o/1740029957336-UDANG-SELINGKUH/6qlizdbxa79s7ob.jpeg', '[{\"src\":\"https:\\/\\/rricoid-assets.obs.ap-southeast-4.myhuaweicloud.com\\/berita\\/Biak\\/o\\/1740029957336-UDANG-SELINGKUH\\/6qlizdbxa79s7ob.jpeg\",\"caption\":\"Udang Selingkuh - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Udang Selingkuh - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Udang Selingkuh - Warisan budaya luhur\"}]', '[\"Nama uniknya berasal dari bentuk tubuh yang mirip udang sekaligus kepiting.\",\"Merauke dikenal sebagai daerah penghasil udang ini.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('noken', 'Tas Noken Papua', 'Pakaian', 'papua', 'Tanah Papua', 'Tas rajutan dari serat kulit kayu yang dibawa di kepala atau punggung, diakui UNESCO sebagai warisan budaya.', 'Noken dipakai untuk membawa hasil kebun, kayu bakar, bahkan menggendong bayi. Tas ini melambangkan kehidupan dan kesuburan dalam budaya Papua.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSnzLLSbd0wddBM8P2zr2eRM3bLv6i51O6qjgJgLjOBcG0elkZXbyRg68w&s=10', '[{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1544816155-12df9643f363?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Mama Papua mengenakan tas Noken rajutan serat kayu alami di dahi kepala\"},{\"src\":\"https:\\/\\/blogger.googleusercontent.com\\/img\\/b\\/R29vZ2xl\\/AVvXsEh-SVgko2JTImRwC-3dGIE_3V2WjQDWi7UenMIhf0SnGo1CmJttJpxxnV_hwox08fANXpSsoel0tv8TE_aAoA78rFTVnMoAuE81Fy1IbGc-1gnbvt3CXADlaPPYzqjppkYJ0hauREqYDMQ\\/s1600\\/Industri-Batik-Hadapi-MEA-271015-Prad-1.jpg\",\"caption\":\"Pola rajutan Noken dengan warna-warni pewarna alami daun dan buah hutan\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=1200&auto=format&fit=crop\",\"caption\":\"Proses pemintalan serat kulit kayu hutan menjadi benang rajut kuat\"}]', '[\"UNESCO menetapkan noken sebagai Warisan Budaya Takbenda pada 2012.\",\"Serat yang dipakai diolah dari kulit kayu atau tanaman hutan.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('kain-kulit-kayu-asei', 'Kain Kulit Kayu Asei', 'Pakaian', 'papua', 'Pulau Asei, Danau Sentani', 'Kain dari kulit kayu yang dipukul hingga lentur lalu dilukis dengan motif alam khas Sentani.', 'Pengrajin Asei mengolah kulit kayu menjadi lembaran yang dilukis dengan motif flora, fauna, dan simbol adat. Dahulu dipakai sebagai busana adat dan kini juga menjadi karya seni.', 'https://indonesiakaya.com/wp-content/uploads/2020/10/kerajinan_kulit_kayu_1290.jpg', '[{\"src\":\"https:\\/\\/indonesiakaya.com\\/wp-content\\/uploads\\/2020\\/10\\/kerajinan_kulit_kayu_1290.jpg\",\"caption\":\"Kain Kulit Kayu Asei - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1761516659497-8478e39d2b26?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kain Kulit Kayu Asei - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Kain Kulit Kayu Asei - Warisan budaya luhur\"}]', '[\"Kulit kayu dipukul-pukul hingga menjadi lembaran lentur.\",\"Motifnya terinspirasi alam dan lambang adat Sentani.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('busana-adat-papua', 'Busana Adat Papua', 'Pakaian', 'papua', 'Tanah Papua', 'Ragam busana tradisional Papua seperti koteka, rok rumbai, dan hiasan kepala yang berbeda antar suku.', 'Papua memiliki ratusan suku dengan busana adat yang beragam. Koteka, rok rumbai dari serat, dan hiasan kepala dikenakan dalam upacara dan perayaan adat.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQqUg0xuRi_w4xr28IcdA_-fFxxxWcpLV0K474-ITL8MA&s', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcQqUg0xuRi_w4xr28IcdA_-fFxxxWcpLV0K474-ITL8MA&s\",\"caption\":\"Busana Adat Papua - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Busana Adat Papua - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1695306441929-0082158cfc27?q=80&w=735&auto=format&fit=crop\",\"caption\":\"Busana Adat Papua - Warisan budaya luhur\"}]', '[\"Setiap suku memiliki gaya busana adat yang berbeda.\",\"Hiasan kepala dan aksesori sering memakai bahan alami dari hutan.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('bakar-batu', 'Bakar Batu', 'Tradisi', 'papua', 'Lembah Baliem & Pegunungan Tengah, Papua', 'Tradisi memasak bersama dengan batu panas di lubang tanah untuk merayakan syukur, pernikahan, atau perdamaian.', 'Batu dipanaskan dalam api lalu ditumpuk bersama sayuran, umbi, dan daging dalam lubang. Seluruh warga berkumpul menikmati hasilnya sebagai tanda kebersamaan.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRcPqN_jZQ4aS8_3kIVcsOZUduqUgMO4pdPRLaLp8nxcg&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcRcPqN_jZQ4aS8_3kIVcsOZUduqUgMO4pdPRLaLp8nxcg&s=10\",\"caption\":\"Bakar Batu - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bakar Batu - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Bakar Batu - Warisan budaya luhur\"}]', '[\"Di Lembah Baliem tradisi ini dikenal dengan sebutan barapen.\",\"Namanya berbeda-beda di tiap daerah pegunungan Papua.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('festival-lembah-baliem', 'Festival Lembah Baliem', 'Tradisi', 'papua', 'Wamena, Papua Pegunungan', 'Festival tahunan di Wamena yang menampilkan perang-perangan suku Dani, Lani, dan Yali serta tarian dan pesta adat.', 'Festival ini mempertemukan berbagai suku pegunungan untuk memperlihatkan budaya mereka. Perang-perangan di festival adalah pertunjukan simbolis, bukan pertempuran sungguhan.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRpGYRYM99xLGiKZxuUPOwkZAJBZvQp75vFKB3EnrvE9g2czTpLi0rZbHXY&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcRpGYRYM99xLGiKZxuUPOwkZAJBZvQp75vFKB3EnrvE9g2czTpLi0rZbHXY&s=10\",\"caption\":\"Festival Lembah Baliem - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Festival Lembah Baliem - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Festival Lembah Baliem - Warisan budaya luhur\"}]', '[\"Festival digelar setiap tahun, biasanya pada bulan Agustus.\",\"Perang-perangan di festival bersifat simbolis dan penuh nilai budaya.\"]', 'Dokumentasi Kebudayaan Nusantara');
INSERT INTO `cultures` (`slug`, `title`, `category`, `island`, `place`, `summary`, `description`, `src`, `gallery`, `funFacts`, `credit`) VALUES ('tari-yospan', 'Tari Yospan', 'Tradisi', 'papua', 'Papua', 'Tarian pergaulan Papua yang riang, gabungan Yosim dan Pancar, diiringi ukulele, gitar, dan tifa.', 'Yospan dibawakan secara berkelompok dalam penyambutan tamu dan perayaan. Gerakannya energik dan menggambarkan keceriaan serta kebersamaan masyarakat Papua.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR4wZtwh9-K9Tn4nBPPZSYko8xIhKbaFtuVOYOleQvstA&s=10', '[{\"src\":\"https:\\/\\/encrypted-tbn0.gstatic.com\\/images?q=tbn:ANd9GcR4wZtwh9-K9Tn4nBPPZSYko8xIhKbaFtuVOYOleQvstA&s=10\",\"caption\":\"Tari Yospan - Dokumentasi utama\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tari Yospan - Keindahan warisan nusantara\"},{\"src\":\"https:\\/\\/images.unsplash.com\\/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=80\",\"caption\":\"Tari Yospan - Warisan budaya luhur\"}]', '[\"Nama Yospan berasal dari gabungan tarian Yosim dan Pancar.\",\"Tarian ini kerap dipentaskan saat menyambut tamu.\"]', 'Dokumentasi Kebudayaan Nusantara');